114	func TestValidateClusterHost(t *testing.T) {
115		t.Parallel()
116		tests := []struct {
117			name    string
118			host    string
119			wantErr bool
120		}{
121			{name: "default cluster", host: defaultClusterHost},
122			{name: "other region", host: "eu-west-1.entire.io"},
123			{name: "single label", host: "localhost"},
124			{name: "host with port", host: "localhost:8080"},
125			{name: "ipv4", host: "10.0.0.1"},
126			{name: "ipv4 with port", host: "10.0.0.1:8080"},
127			// IPv6 takes a different path through validateClusterHost: the
128			// host must be bracketed for url.Parse to round-trip, and
129			// u.Hostname() strips the brackets before net.ParseIP sees it.
130			{name: "ipv6 with port", host: "[::1]:8080"},
131			// The token-leak primitive: userinfo demotes the real cluster so the
132			// request (and basic-auth token) targets evil.com.
133			{name: "userinfo smuggle", host: "aws-us-east-2.entire.io@evil.com", wantErr: true},
134			{name: "path smuggle", host: "aws-us-east-2.entire.io/../evil", wantErr: true},
135			{name: "query smuggle", host: "aws-us-east-2.entire.io?x=1", wantErr: true},
136			{name: "fragment smuggle", host: "aws-us-east-2.entire.io#x", wantErr: true},
137			{name: "scheme prefix", host: "https://evil.com", wantErr: true},
138			{name: "empty", host: "", wantErr: true},
139			{name: "whitespace", host: "   ", wantErr: true},
140			{name: "leading hyphen label", host: "-bad.entire.io", wantErr: true},
141			{name: "space in host", host: "evil .com", wantErr: true},
142		}
143		for _, tt := range tests {
144			t.Run(tt.name, func(t *testing.T) {
145				t.Parallel()
